import { Component, h, Host, Prop } from '@stencil/core';
import { TreeViewSize } from '../../../types';

/**
 * @slot default - default slot for tree nodes
 * @slot label - label slot for the text of the group
 */
@Component({
  tag: 'groupui-tree-group',
  styleUrl: 'tree-group.scss',
  shadow: true,
})
export class TreeGroup {
  /**
   * @internal Size of all tree nodes. Available sizes are 'm' (default) and 's'
   */
  @Prop({ reflect: true }) readonly size: TreeViewSize = 'm';

  render() {
    return (
      <Host role="treeitem" aria-labelledby="tree-group-label">
        <div role="tree">
          <div id="tree-group-label">
            <slot name="label"></slot>
          </div>
          <slot></slot>
        </div>
      </Host>
    );
  }
}
